namespace Fanex.Age.UI.TotalBets
{

    public partial class NextGoal_Page : TotalBets_Page
    {

        #region Constant
        private const int SCORE_COLUMN_COUNT = 5;
        #endregion

        #region Override

        /// <summary>
        /// Render next goal table
        /// The data has the following format
        /// league1 match1  score1
        /// league1 match1  score2
        /// league1 match2  score3
        /// league1 match2  score4
        /// 
        /// </summary>
        /// <param name="writer"></param>
        public override void RenderContent(HtmlTextWriter writer)
        {
            DataTable NextGoalList = View as DataTable;

            NextGoal_Template tpl = new NextGoal_Template();
            tpl.Contents.LeagueContents.Clear();

            if (NextGoalList.Rows.Count > 0)
            {
                tpl.Contents.NotFoundContent.Hide();

                // Render league content
                NextGoal_Contents_LeagueContents_Block leagueBlock = new NextGoal_Contents_LeagueContents_Block();
                NextGoal_Contents_LeagueContents_MatchContents_Block matchBlock = new NextGoal_Contents_LeagueContents_MatchContents_Block();
                NextGoal_Contents_LeagueContents_MatchContents_ScoreContents_Block scoreBlock = new NextGoal_Contents_LeagueContents_MatchContents_ScoreContents_Block();
                NextGoal_Contents_LeagueContents_MatchContents_ScoreContents_BetScores_Block betScoreBlock = new NextGoal_Contents_LeagueContents_MatchContents_ScoreContents_BetScores_Block();
                int currentRowIndex = 0;
                int rowCount = NextGoalList.Rows.Count;

                // Loop for league
                int matchIndex = 1;
                while (currentRowIndex < rowCount)
                {
                    // Render league
                    int leagueId = Convert.ToInt32(NextGoalList.Rows[currentRowIndex]["leagueid"]);
                    int currentLeagueId = leagueId;

                    // Loop for match
                    leagueBlock.MatchContents.Clear();
                    while (currentRowIndex < rowCount && currentLeagueId == leagueId)
                    {
                        currentLeagueId = leagueId;
                        // Render league info
                        leagueBlock.LeagueName = Sunplus.Agent.Model.BL.Cache.CacheRef.GetLeagueName(currentLeagueId);
                        // Render match
                        int currentMatchId = Convert.ToInt32(NextGoalList.Rows[currentRowIndex]["matchid"]);

                        matchBlock.NoValue = matchIndex.ToString();
                        matchBlock.MatchId = currentMatchId.ToString();
                        matchBlock.Home = Sunplus.Agent.Model.BL.Cache.CacheRef.GetTeamName(NextGoalList.Rows[currentRowIndex]["homeid"]) + ((bool)NextGoalList.Rows[currentRowIndex]["isNeutral"] ? Resources.Lang.IsNeutral : string.Empty);
                        matchBlock.Away = Sunplus.Agent.Model.BL.Cache.CacheRef.GetTeamName(NextGoalList.Rows[currentRowIndex]["awayid"]);
                        matchBlock.BetType = Fanex.Age.UI.Common.BetListByBetTypeMatch;
                        matchBlock.ColorClass = (matchIndex % 2) == 0 ? Fanex.Age.UI.Common.RowBgEven : Fanex.Age.UI.Common.RowBgOdd;
                        matchBlock.ColorOver = Fanex.Age.UI.Common.RowBgOver;
                        matchBlock.TimeValue = NextGoalList.Rows[currentRowIndex]["showtime"].ToString();
                        matchBlock.ScoreContents.Clear();
                        // Loop for score
                        // Render all score to a table 5 columns and n rows
                        int scoreIndex = 0;
                        int matchId = currentMatchId;
                        scoreBlock.BetScores.Clear();
                        while (currentRowIndex < rowCount && currentMatchId == matchId)
                        {
                            currentMatchId = matchId;
                            // Render score
                            int awayTotalScore = Convert.ToInt32(NextGoalList.Rows[currentRowIndex]["away_total"]);
                            int homeTotalScore = Convert.ToInt32(NextGoalList.Rows[currentRowIndex]["home_total"]);

                            betScoreBlock.BetScoreContents.Show();
                            betScoreBlock.BetScoreContents.AwayScore = NextGoalList.Rows[currentRowIndex]["liveawayscore"].ToString();
                            betScoreBlock.BetScoreContents.HomeScore = NextGoalList.Rows[currentRowIndex]["livehomescore"].ToString();

                            if (scoreIndex == 0)
                            {
                                betScoreBlock.BetScoreContents.LastScoreContents.Show();
                                betScoreBlock.BetScoreContents.NextScoreContents.Hide();
                                betScoreBlock.BetScoreContents.LastScoreContents.MatchId = currentMatchId.ToString();
                                betScoreBlock.BetScoreContents.LastScoreContents.SubGoal = NegativeNumberBlueColor(homeTotalScore - awayTotalScore);
                            }
                            else
                            {
                                betScoreBlock.BetScoreContents.LastScoreContents.Hide();
                                betScoreBlock.BetScoreContents.NextScoreContents.Show();
                                betScoreBlock.BetScoreContents.NextScoreContents.SubGoal = NegativeNumberBlueColor(homeTotalScore - awayTotalScore);
                                betScoreBlock.BetScoreContents.NextScoreContents.WinLost = PositiveNumberRedColor(NextGoalList.Rows[currentRowIndex]["winlost"]);
                            }
                            scoreBlock.BetScores.Append(betScoreBlock);


                            scoreIndex++;
                            // Full column
                            if (scoreIndex % SCORE_COLUMN_COUNT == 0)
                            {
                                matchBlock.ScoreContents.Append(scoreBlock);
                                scoreBlock.BetScores.Clear();
                            }
                            // Move to next row
                            currentRowIndex++;
                            if (currentRowIndex < rowCount)
                            {
                                matchId = Convert.ToInt32(NextGoalList.Rows[currentRowIndex]["matchid"]);
                            }
                        }
                        // Fill the redundant score column
                        if (scoreIndex % SCORE_COLUMN_COUNT > 0)
                        {
                            betScoreBlock.BetScoreContents.Hide();
                            for (; scoreIndex % SCORE_COLUMN_COUNT > 0; scoreIndex++)
                            {
                                scoreBlock.BetScores.Append(betScoreBlock);
                            }
                            matchBlock.ScoreContents.Append(scoreBlock);
                        }

                        leagueBlock.MatchContents.Append(matchBlock);
                        matchIndex++;
                        if (currentRowIndex < rowCount)
                        {
                            leagueId = Convert.ToInt32(NextGoalList.Rows[currentRowIndex]["leagueid"]);
                        }
                    }
                    tpl.Contents.LeagueContents.Append(leagueBlock);
                }
            }

            if (_fullMode)
            {
                writer.Write(tpl);
            }
            else
            {
                writer.Write(tpl.Contents);
            }   
        }

        public override object ValidateRequest(System.Collections.Hashtable p)
        {
            return null;
        }

        public override object InvokeData(System.Collections.Hashtable p)
        {
            return _TotalBetsBO.GetNextGoal();
        }
        #endregion

        #region Utility

        /// <summary>
        /// Round color for negative number
        /// </summary>
        /// <param name="number"></param>
        /// <returns></returns>
        private static string NegativeNumberBlueColor(object number)
        {
            return (int)number < 0 ? "<font color='blue'>" + number.ToString() + "</font>" : number.ToString();
        }
        private static String PositiveNumberRedColor(object number)
        {
            return ((decimal)number > 0) ? "<font color='red'>" + Formater.DecFormat(number, 0) + "</font>" : Formater.DecFormat(number, 0);
        }
        #endregion
    }

}
